=== FILE: apb_regs.v ===
`timescale 1ns/1ps
`default_nettype none

// apb_regs: four 32-bit read/write registers behind an APB4 subordinate port.
// Implements interface_spec.md per microarchitecture.md:
//   - zero wait states (pready tied high), no state machine
//   - access = psel && penable is the only cycle with an effect
//   - mapped = word aligned and offset 0x0..0xC; otherwise PSLVERR
//   - synchronous, active-low reset clears all registers
module apb_regs #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output wire [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

    localparam integer STRB_WIDTH = DATA_WIDTH / 8;

    // ------------------------------------------------------------------
    // Register state: four separate flops (no memory array).
    // ------------------------------------------------------------------
    reg [DATA_WIDTH-1:0] reg0;
    reg [DATA_WIDTH-1:0] reg1;
    reg [DATA_WIDTH-1:0] reg2;
    reg [DATA_WIDTH-1:0] reg3;

    // ------------------------------------------------------------------
    // Decode
    // ------------------------------------------------------------------
    wire       access = psel && penable;
    wire       mapped = (paddr[1:0] == 2'b00) &&
                        (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
    wire [1:0] idx    = paddr[3:2];
    wire       wr_en  = access && pwrite && mapped;
    wire       rd_en  = access && !pwrite && mapped;

    // ------------------------------------------------------------------
    // Byte merge: copy each pwdata byte whose strobe bit is set.
    // ------------------------------------------------------------------
    wire [DATA_WIDTH-1:0] wmask;
    genvar b;
    generate
        for (b = 0; b < STRB_WIDTH; b = b + 1) begin : g_wmask
            assign wmask[8*b +: 8] = {8{pstrb[b]}};
        end
    endgenerate

    wire [DATA_WIDTH-1:0] merged0 = (reg0 & ~wmask) | (pwdata & wmask);
    wire [DATA_WIDTH-1:0] merged1 = (reg1 & ~wmask) | (pwdata & wmask);
    wire [DATA_WIDTH-1:0] merged2 = (reg2 & ~wmask) | (pwdata & wmask);
    wire [DATA_WIDTH-1:0] merged3 = (reg3 & ~wmask) | (pwdata & wmask);

    // ------------------------------------------------------------------
    // Register write, synchronous active-low reset
    // ------------------------------------------------------------------
    always @(posedge pclk) begin
        if (!presetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else if (wr_en) begin
            if (idx == 2'd0) reg0 <= merged0;
            if (idx == 2'd1) reg1 <= merged1;
            if (idx == 2'd2) reg2 <= merged2;
            if (idx == 2'd3) reg3 <= merged3;
        end
    end

    // ------------------------------------------------------------------
    // Read data: combinational 4:1 mux, zero unless mapped read access
    // ------------------------------------------------------------------
    wire [DATA_WIDTH-1:0] rd_mux = idx[1] ? (idx[0] ? reg3 : reg2)
                                          : (idx[0] ? reg1 : reg0);

    assign prdata  = rd_en ? rd_mux : {DATA_WIDTH{1'b0}};
    assign pready  = 1'b1;
    assign pslverr = access && !mapped;

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Design-intent properties (default parameters). The decode below is
    // written independently of `mapped` above.
    // ------------------------------------------------------------------
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge pclk) f_past_valid <= 1'b1;

    wire f_mapped = (paddr[1:0] == 2'b00) && (paddr < 16);
    wire f_access = psel && penable;

    // Manager follows APB4
    always @(*) begin
        if (!f_past_valid) assume (!presetn);
        if (!presetn)      assume (!psel);
        if (penable)       assume (psel);
    end

    always @(posedge pclk) begin
        if (f_past_valid && f_access)
            assume ($past(psel) && !$past(penable));
        if (f_past_valid && presetn && $past(psel) && !$past(penable)) begin
            assume (psel && penable);
            assume (paddr  == $past(paddr));
            assume (pwrite == $past(pwrite));
            assume (pwdata == $past(pwdata));
            assume (pstrb  == $past(pstrb));
        end
    end

    // Response rules
    always @(*) begin
        assert (pready);
        if (!f_access) begin
            assert (prdata == {DATA_WIDTH{1'b0}});
            assert (!pslverr);
        end else begin
            assert (pslverr == !f_mapped);
            if (!pwrite && !f_mapped) assert (prdata == {DATA_WIDTH{1'b0}});
            if (!pwrite && f_mapped && paddr[3:2] == 2'd0) assert (prdata == reg0);
            if (!pwrite && f_mapped && paddr[3:2] == 2'd1) assert (prdata == reg1);
            if (!pwrite && f_mapped && paddr[3:2] == 2'd2) assert (prdata == reg2);
            if (!pwrite && f_mapped && paddr[3:2] == 2'd3) assert (prdata == reg3);
        end
    end

    // Register rules
    always @(posedge pclk) begin
        if (f_past_valid) begin
            if (!$past(presetn)) begin
                assert (reg0 == {DATA_WIDTH{1'b0}});
                assert (reg1 == {DATA_WIDTH{1'b0}});
                assert (reg2 == {DATA_WIDTH{1'b0}});
                assert (reg3 == {DATA_WIDTH{1'b0}});
            end else begin
                if (!$past(f_access && pwrite && f_mapped && paddr[3:2] == 2'd0))
                    assert (reg0 == $past(reg0));
                if (!$past(f_access && pwrite && f_mapped && paddr[3:2] == 2'd1))
                    assert (reg1 == $past(reg1));
                if (!$past(f_access && pwrite && f_mapped && paddr[3:2] == 2'd2))
                    assert (reg2 == $past(reg2));
                if (!$past(f_access && pwrite && f_mapped && paddr[3:2] == 2'd3))
                    assert (reg3 == $past(reg3));
            end
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
