`timescale 1ns/1ps

// Self-checking directed testbench for apb_regs.
// Drives inputs 0 ns after the falling edge, samples 1 ns later (well before
// the next rising edge), so there is no race with the design.
module apb_regs_tb;

    reg         pclk = 1'b0;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    wire [31:0] prdata;
    wire        pready;
    wire        pslverr;

    always #5 pclk = ~pclk;

    apb_regs #(
        .ADDR_WIDTH(8),
        .DATA_WIDTH(32)
    ) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    integer           passed;
    integer           failed;
    integer           i;
    integer           got_nonce;
    reg [8*64-1:0]    nonce;
    reg [31:0]        model [0:3];
    reg [31:0]        rd;
    reg               er;

    // ------------------------------------------------------------------
    // Reference functions (independent of the RTL)
    // ------------------------------------------------------------------
    function ref_mapped;
        input [7:0] a;
        begin
            ref_mapped = (a[1:0] == 2'b00) && (a < 8'h10);
        end
    endfunction

    function [31:0] merge_ref;
        input [31:0] old;
        input [31:0] data;
        input [3:0]  strb;
        begin
            merge_ref = { (strb[3] ? data[31:24] : old[31:24]),
                          (strb[2] ? data[23:16] : old[23:16]),
                          (strb[1] ? data[15:8]  : old[15:8]),
                          (strb[0] ? data[7:0]   : old[7:0]) };
        end
    endfunction

    // ------------------------------------------------------------------
    // Checks
    // ------------------------------------------------------------------
    task check_bit;
        input integer id;
        input         got;
        input         exp;
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("check %0d failed at %0t: got %b expected %b (paddr=%h)",
                       id, $time, got, exp, paddr);
            end
        end
    endtask

    task check_word;
        input integer id;
        input [31:0]  got;
        input [31:0]  exp;
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("check %0d failed at %0t: got %h expected %h (paddr=%h)",
                       id, $time, got, exp, paddr);
            end
        end
    endtask

    // ------------------------------------------------------------------
    // Bus tasks
    // ------------------------------------------------------------------
    task drive_idle;
        begin
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = 8'h00;
            pwdata  = 32'h0000_0000;
            pstrb   = 4'h0;
        end
    endtask

    // n idle cycles; prdata and pslverr must be quiet, pready high
    task idle;
        input integer n;
        integer j;
        begin
            for (j = 0; j < n; j = j + 1) begin
                @(negedge pclk);
                drive_idle;
                #1;
                check_word(100, prdata, 32'h0000_0000);
                check_bit (101, pslverr, 1'b0);
                check_bit (102, pready, 1'b1);
            end
        end
    endtask

    // One APB4 transfer: setup phase then a single access phase.
    task apb_xfer;
        input         w;
        input  [7:0]  addr;
        input  [31:0] data;
        input  [3:0]  strb;
        output [31:0] rdata;
        output        err;
        begin
            // setup phase
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = w;
            paddr   = addr;
            pwdata  = data;
            pstrb   = w ? strb : 4'h0;
            #1;
            check_word(1, prdata, 32'h0000_0000);   // quiet in setup
            check_bit (2, pslverr, 1'b0);
            check_bit (3, pready, 1'b1);
            // access phase
            @(negedge pclk);
            penable = 1'b1;
            #1;
            check_bit (4, pready, 1'b1);            // zero wait states
            rdata = prdata;
            err   = pslverr;
        end
    endtask

    task write_chk;
        input [7:0]  a;
        input [31:0] d;
        input [3:0]  s;
        begin
            apb_xfer(1'b1, a, d, s, rd, er);
            check_bit(10, er, !ref_mapped(a));
            if (ref_mapped(a))
                model[a[3:2]] = merge_ref(model[a[3:2]], d, s);
        end
    endtask

    task read_chk;
        input [7:0] a;
        begin
            apb_xfer(1'b0, a, 32'h0000_0000, 4'h0, rd, er);
            check_bit (11, er, !ref_mapped(a));
            check_word(12, rd, ref_mapped(a) ? model[a[3:2]] : 32'h0000_0000);
        end
    endtask

    task read_all;
        begin
            read_chk(8'h00);
            read_chk(8'h04);
            read_chk(8'h08);
            read_chk(8'h0C);
        end
    endtask

    task unmapped_chk;
        input [7:0] a;
        begin
            write_chk(a, 32'hFFFF_FFFF, 4'hF);
            read_chk(a);
        end
    endtask

    task do_reset;
        integer j;
        begin
            @(negedge pclk);
            presetn = 1'b0;
            drive_idle;
            for (j = 0; j < 3; j = j + 1) begin
                @(negedge pclk);
                #1;
                check_word(20, prdata, 32'h0000_0000);
                check_bit (21, pslverr, 1'b0);
                check_bit (22, pready, 1'b1);
            end
            @(negedge pclk);
            presetn = 1'b1;
            model[0] = 32'h0000_0000;
            model[1] = 32'h0000_0000;
            model[2] = 32'h0000_0000;
            model[3] = 32'h0000_0000;
        end
    endtask

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin
        passed    = 0;
        failed    = 0;
        got_nonce = 0;
        nonce     = {(8*64){1'b0}};
        presetn   = 1'b0;
        drive_idle;
        for (i = 0; i < 4; i = i + 1)
            model[i] = 32'h0000_0000;

        // 1. Reset and reset values (back-to-back reads)
        do_reset;
        read_all;
        idle(2);

        // 2. Full writes to every register, back to back, then read back
        write_chk(8'h00, 32'h1234_5678, 4'hF);
        write_chk(8'h04, 32'h9ABC_DEF0, 4'hF);
        write_chk(8'h08, 32'hA5A5_5A5A, 4'hF);
        write_chk(8'h0C, 32'hDEAD_BEEF, 4'hF);
        read_all;
        idle(1);

        // 3. Write then read with idle gaps between transfers
        write_chk(8'h04, 32'hFFFF_FFFF, 4'hF);
        idle(3);
        read_chk(8'h04);
        idle(1);
        read_chk(8'h00);
        write_chk(8'h00, 32'h0F0F_0F0F, 4'hF);
        read_chk(8'h00);
        idle(2);

        // 4. pstrb partial writes: every strobe pattern on REG2, then REG1
        for (i = 0; i < 16; i = i + 1) begin
            write_chk(8'h08, {4{i[7:0]}} ^ 32'hC3A5_965A, i[3:0]);
            read_chk(8'h08);
        end
        idle(1);
        for (i = 15; i >= 0; i = i - 1) begin
            write_chk(8'h04, {4{i[7:0]}} ^ 32'h3C5A_69A5, i[3:0]);
            if (i[1:0] == 2'b01) idle(1);
            read_chk(8'h04);
        end

        // 5. All-zero strobe changes nothing and completes without error
        write_chk(8'h0C, 32'h0000_0000, 4'h0);
        read_chk(8'h0C);
        read_all;
        idle(2);

        // 6. PSLVERR policy: misaligned and out-of-range addresses
        unmapped_chk(8'h01);
        unmapped_chk(8'h02);
        unmapped_chk(8'h03);
        unmapped_chk(8'h05);
        unmapped_chk(8'h06);
        unmapped_chk(8'h07);
        unmapped_chk(8'h09);
        unmapped_chk(8'h0A);
        unmapped_chk(8'h0B);
        unmapped_chk(8'h0D);
        unmapped_chk(8'h0E);
        unmapped_chk(8'h0F);
        unmapped_chk(8'h10);
        unmapped_chk(8'h11);
        unmapped_chk(8'h14);
        unmapped_chk(8'h18);
        unmapped_chk(8'h1C);
        unmapped_chk(8'h20);
        unmapped_chk(8'h40);
        unmapped_chk(8'h80);
        unmapped_chk(8'hF0);
        unmapped_chk(8'hFC);
        unmapped_chk(8'hFF);
        idle(1);
        // no register corrupted by unmapped writes
        read_all;

        // 7. Mapped and unmapped transfers interleaved back to back
        write_chk(8'h00, 32'hCAFE_F00D, 4'hF);
        unmapped_chk(8'h12);
        read_chk(8'h00);
        write_chk(8'h0C, 32'h1357_9BDF, 4'h6);
        read_chk(8'h1C);
        read_chk(8'h0C);
        idle(2);

        // 8. Reset again: registers return to zero
        write_chk(8'h04, 32'h8765_4321, 4'hF);
        write_chk(8'h08, 32'h2468_ACE0, 4'hF);
        do_reset;
        read_all;
        write_chk(8'h00, 32'h5555_AAAA, 4'hF);
        read_chk(8'h00);
        read_chk(8'h04);
        idle(2);

        // Verdict
        got_nonce = $value$plusargs("nirmaan_nonce=%s", nonce);
        if (got_nonce == 0)
            $display("apb_regs_tb: no nirmaan_nonce plusarg given");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
